+PushKind push_plan(Canvas *c, PushRow *rows, int *count) {
+  int n = 0;
+  int64_t total_ns = 0;
+  Group cur = {0};
+  for (int y = 0; y < c->h; y++) {
+    int x0, x1;
+    if (!canvas_dirty_row(c, y, &x0, &x1)) continue;
+    Group one = {y, y, x0, x1, 1, x1 - x0 + 1};
+    if (n == 0) {
+      cur = one;
+    } else {
+      Group merged = merge(&cur, &one);
+      if (group_cost(&merged) <= group_cost(&cur) + group_cost(&one)) {
+        cur = merged;
+      } else {
