#include <M5Unified.h>
#include <esp_heap_caps.h>

extern "C" {
#include "core/canvas.h"
#include "core/push_plan.h"
#include "hacks/registry.h"
#include "runner/button_latch.h"
#include "runner/hack_runner.h"
#include "runner/overlay.h"
#include "runner/rotation.h"
#include "runner/start_pick.h"
}

/* Hacks run on loopTask, whose 8 KB default stack is too small: Rorschach
 * keeps a 9.6 KB array of rectangles on the stack. */
SET_LOOP_TASK_STACK_SIZE(16 * 1024);

static const int kSize = 466;
static const uint32_t kSliceUs = 10000;
/* Build with -DSTART_HACK=\"galaxy\" (see AGENTS.md) to always start on one
 * hack; otherwise boot picks one at random. */
#ifdef START_HACK
static const char *const kForcedStart = START_HACK;
#else
static const char *const kForcedStart = nullptr;
#endif

static const uint32_t kStatsEveryMs = 5000;
static const uint32_t kNameShownMs = 5000;

/* Seconds before moving on to the next hack; build with -DROTATE_SECONDS=5 to
 * shorten it for leak testing, or 0 to stay put. */
#ifndef ROTATE_SECONDS
#define ROTATE_SECONDS 90
#endif
static const uint32_t kRotateMs = ROTATE_SECONDS * 1000u;
static const int kNameY = kSize / 2;
static const int kFpsY = kSize - 40;

/* M5Unified reads the buttons as active-low GPIOs, and only inside
 * M5.update(), so a press during a long hack step would go unseen. A small
 * task on the otherwise idle core 0 samples both pins every few milliseconds
 * (it preempts nothing the hacks run on) and a latch keeps the presses. The
 * pin must hold its new level for the settle time, which rejects bounce. */
static const gpio_num_t kPinButtonA = GPIO_NUM_2;
static const gpio_num_t kPinButtonB = GPIO_NUM_1;
static const uint32_t kButtonPollMs = 5;
static const uint32_t kButtonSettleMs = 30;

static ButtonLatch latchA, latchB;

static void buttonTask(void *) {
  for (;;) {
    uint32_t now = millis();
    button_latch_sample(&latchA, gpio_get_level(kPinButtonA) == 0, now);
    button_latch_sample(&latchB, gpio_get_level(kPinButtonB) == 0, now);
    vTaskDelay(pdMS_TO_TICKS(kButtonPollMs));
  }
}

static Canvas canvas;
static HackRunner *runner;
static Overlay overlay;
static Rotation rotation;
static uint32_t frames;
static uint32_t statsAt;
static uint32_t stepUs, pushUs, waitUs, rowsPushed;
static PushRow pushRows[kSize];

static void halt(const char *msg) {
  Serial.println(msg);
  M5.Display.fillScreen(0x000000);
  M5.Display.setTextColor(0xFFFFFF);
  M5.Display.setTextDatum(middle_center);
  M5.Display.drawString(msg, M5.Display.width() / 2, M5.Display.height() / 2);
  for (;;) delay(1000);
}

static void resetStats() {
  frames = stepUs = pushUs = waitUs = rowsPushed = 0;
  statsAt = millis();
}

/* step/push/wait are mean milliseconds per frame spent in the hack, in
 * pushImage, and waiting out what is left of the hack's requested delay after
 * the push (including button polling). rows is the mean number of canvas rows
 * sent to the display per frame (466 is a full push), counting overlay redraws
 * made while waiting. */
static void printStats(const char *tag) {
  float n = frames ? (float)frames : 1.0f;
  Serial.printf(
      "%s %s fps=%.1f step=%.1fms push=%.1fms wait=%.1fms rows=%.0f heap=%u "
      "psram=%u\n",
      tag, g_hacks[runner_index(runner)]->name,
      frames * 1000.0f / kStatsEveryMs, stepUs / n / 1000.0f,
      pushUs / n / 1000.0f, waitUs / n / 1000.0f, rowsPushed / n,
      (unsigned)ESP.getFreeHeap(),
      (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
}

/* Overlay text is stamped into the canvas just for the push, then the pixels
 * under it are put back. Drawing on the display after the push flickered,
 * because the next push wiped the text for a moment. The canvas must end up
 * as the hack left it, since hacks draw incrementally. M5Canvas wraps the
 * canvas buffer so M5GFX's fonts can draw into it; the DejaVu fonts are 1-bit,
 * so only pure black and white are written (the same in either byte order). */
static const int kPatchMaxH = 48;
static const int kPatchMargin = 2;

struct Patch {
  int x, y, w, h;
  uint16_t *saved;
};

static M5Canvas stamp;
static Patch namePatch, fpsPatch;

static void stampText(Patch *p, const char *text, int cx, int cy,
                      const lgfx::IFont *font) {
  stamp.setFont(font);
  stamp.setTextDatum(middle_center);
  int w = stamp.textWidth(text) + 2 * kPatchMargin;
  int h = stamp.fontHeight() + 2 * kPatchMargin;
  p->w = w < kSize ? w : kSize;
  p->h = h < kPatchMaxH ? h : kPatchMaxH;
  p->x = cx - p->w / 2;
  p->y = cy - p->h / 2;
  canvas_copy_rect(&canvas, p->x, p->y, p->w, p->h, p->saved);
  stamp.setTextColor(0x000000);
  for (int dy = -1; dy <= 1; dy++)
    for (int dx = -1; dx <= 1; dx++)
      if (dx || dy) stamp.drawString(text, cx + dx, cy + dy);
  stamp.setTextColor(0xFFFFFF);
  stamp.drawString(text, cx, cy);
  canvas_mark_dirty(&canvas, p->x, p->y, p->w, p->h);
}

static void unstamp(Patch *p) {
  if (p->w) canvas_paste_rect(&canvas, p->x, p->y, p->w, p->h, p->saved);
  p->w = 0;
}

/* Whole rows are sent inside one startWrite: each call then costs about 5 us
 * instead of 16. */
static void sinkBegin(void *) { M5.Display.startWrite(); }
static void sinkEnd(void *) { M5.Display.endWrite(); }
static void sinkRow(void *, int y, int x0, int x1) {
  M5.Display.pushImage(x0, y, x1 - x0 + 1, 1, canvas.px + y * kSize + x0);
}
static void sinkAll(void *) {
  M5.Display.pushImage(0, 0, kSize, kSize, canvas.px);
}
static const PushSink pushSink = {nullptr, sinkBegin, sinkRow, sinkAll, sinkEnd};

static void present() {
  uint32_t now = millis();
  if (overlay_name_visible(&overlay, now))
    stampText(&namePatch, g_hacks[runner_index(runner)]->name, kSize / 2,
              kNameY, &fonts::DejaVu24);
  if (overlay_fps_visible(&overlay)) {
    char text[16];
    overlay_fps_text(&overlay, text, sizeof text);
    stampText(&fpsPatch, text, kSize / 2, kFpsY, &fonts::DejaVu18);
  }
  overlay_drawn(&overlay, now);
  rowsPushed += push_present(&canvas, pushRows, &pushSink);
  unstamp(&fpsPatch);
  unstamp(&namePatch);
}

/* Whatever started the hack, the name shows again, the rotation countdown
 * restarts and the stats begin afresh. */
static void hackStarted() {
  uint32_t now = millis();
  overlay_hack_started(&overlay, now);
  rotation_reset(&rotation, now);
  resetStats();
}

/* Returns true if a button switched hacks. */
static bool pollButtons() {
  bool switched = false;
  uint32_t pressedAt = 0;
  if (button_latch_take(&latchA, &pressedAt)) {
    runner_next(runner);
    switched = true;
  }
  if (button_latch_take(&latchB, &pressedAt)) {
    runner_prev(runner);
    switched = true;
  }
  if (switched) {
    Serial.printf("switch -> %s press_waited=%ums heap=%u psram=%u\n",
                  g_hacks[runner_index(runner)]->name,
                  (unsigned)(millis() - pressedAt),
                  (unsigned)ESP.getFreeHeap(),
                  (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
    hackStarted();
  }
  return switched;
}

/* Returns true if the timer moved on to the next hack. */
static bool pollRotation() {
  if (!rotation_due(&rotation, millis())) return false;
  runner_next(runner);
  Serial.printf("rotate -> %s heap=%u psram=%u\n",
                g_hacks[runner_index(runner)]->name, (unsigned)ESP.getFreeHeap(),
                (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
  hackStarted();
  return true;
}

/* A tap anywhere toggles the fps readout. Call right after M5.update(), which
 * is the only place the touch edge is recorded. */
static void pollTouch() {
  if (M5.Touch.getDetail().wasPressed()) overlay_toggle_fps(&overlay);
}

void setup() {
  auto cfg = M5.config();
  M5.begin(cfg);
  Serial.begin(115200);
  M5.Display.setSwapBytes(false);

  button_latch_init(&latchA, kButtonSettleMs);
  button_latch_init(&latchB, kButtonSettleMs);
  xTaskCreatePinnedToCore(buttonTask, "buttons", 2048, nullptr, 2, nullptr, 0);

  if (canvas_init(&canvas, kSize, kSize, ps_malloc) != 0)
    halt("PSRAM alloc failed");
  stamp.setBuffer(canvas.px, kSize, kSize, 16);
  namePatch.saved = (uint16_t *)ps_malloc(kSize * kPatchMaxH * sizeof(uint16_t));
  fpsPatch.saved = (uint16_t *)ps_malloc(kSize * kPatchMaxH * sizeof(uint16_t));
  if (!namePatch.saved || !fpsPatch.saved) halt("PSRAM alloc failed");
  runner = runner_create(&canvas);
  if (!runner) halt("hack start failed");
  int first = start_pick_index(g_hacks, g_hack_count, kForcedStart, esp_random());
  if (kForcedStart && start_find_hack(g_hacks, g_hack_count, kForcedStart) < 0)
    Serial.printf("START_HACK \"%s\" not found, starting at random\n",
                  kForcedStart);
  if (runner_start(runner, first) != 0) halt("hack start failed");
  overlay_init(&overlay, kNameShownMs);
  rotation_init(&rotation, kRotateMs, millis());
  hackStarted();
  printStats("boot");
  resetStats();
}

void loop() {
  M5.update();
  if (!pollButtons()) pollRotation();
  pollTouch();

  uint32_t t0 = micros();
  unsigned long delayUs = runner_step(runner);
  uint32_t t1 = micros();
  present();
  uint32_t t2 = micros();
  frames++;
  overlay_frame(&overlay, millis());
  stepUs += t1 - t0;
  pushUs += t2 - t1;

  /* Only the push counts against the delay. A hack's delay is the pause after
   * it draws, so a hack that asks for a one-second hold must still get it
   * however long its own step took. */
  unsigned long waitUsTarget = runner_remaining_delay_us(delayUs, t2 - t1);
  uint32_t waitedUs = 0;
  bool switched = false;
  while (!switched && waitedUs < waitUsTarget) {
    uint32_t slice =
        waitUsTarget - waitedUs < kSliceUs ? waitUsTarget - waitedUs : kSliceUs;
    delayMicroseconds(slice);
    waitedUs += slice;
    M5.update();
    switched = pollButtons() || pollRotation();
    if (!switched) pollTouch();
    if (!switched && overlay_wants_redraw(&overlay, millis())) present();
  }
  if (!switched) waitUs += micros() - t2;

  if (millis() - statsAt >= kStatsEveryMs) {
    printStats("run");
    resetStats();
  }
}
#include "runner/overlay.h"

#include <stdio.h>

#define FPS_WINDOW_MS 1000u

void overlay_init(Overlay *o, uint32_t name_ms) {
  *o = (Overlay){.name_ms = name_ms};
}

void overlay_hack_started(Overlay *o, uint32_t now_ms) {
  o->name_armed = true;
  o->name_started_ms = now_ms;
  o->fps_window_start_ms = now_ms;
  o->fps_window_frames = 0;
  o->has_fps = false;
}

void overlay_toggle_fps(Overlay *o) { o->fps_on = !o->fps_on; }

void overlay_frame(Overlay *o, uint32_t now_ms) {
  o->fps_window_frames++;
  uint32_t elapsed = now_ms - o->fps_window_start_ms;
  if (elapsed >= FPS_WINDOW_MS) {
    o->fps = o->fps_window_frames * 1000.0f / elapsed;
    o->has_fps = true;
    o->fps_window_start_ms = now_ms;
    o->fps_window_frames = 0;
  }
}

bool overlay_name_visible(const Overlay *o, uint32_t now_ms) {
  return o->name_armed && now_ms - o->name_started_ms < o->name_ms;
}

bool overlay_fps_visible(const Overlay *o) { return o->fps_on; }

void overlay_fps_text(const Overlay *o, char *buf, size_t size) {
  if (o->has_fps)
    snprintf(buf, size, "%.1f fps", (double)o->fps);
  else
    snprintf(buf, size, "-- fps");
}

bool overlay_wants_redraw(const Overlay *o, uint32_t now_ms) {
  return o->drawn_name != overlay_name_visible(o, now_ms) ||
         o->drawn_fps != o->fps_on;
}

void overlay_drawn(Overlay *o, uint32_t now_ms) {
  o->drawn_name = overlay_name_visible(o, now_ms);
  o->drawn_fps = o->fps_on;
}
#include "core/canvas.h"

#include <math.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

/* The ESP32 has a 32-bit long; clip arithmetic needs 64 bits to be safe. */
typedef int64_t wide_t;

static void mark_all_dirty(Canvas *c) {
  for (int y = 0; y < c->h; y++) {
    c->dirty_x0[y] = 0;
    c->dirty_x1[y] = (int16_t)(c->w - 1);
  }
}

/* The caller has already clipped x0..x1 and y to the canvas. */
static inline void mark_span(Canvas *c, wide_t x0, wide_t x1, wide_t y) {
  if (x0 < c->dirty_x0[y]) c->dirty_x0[y] = (int16_t)x0;
  if (x1 > c->dirty_x1[y]) c->dirty_x1[y] = (int16_t)x1;
}

int canvas_init(Canvas *c, int w, int h, void *(*alloc)(size_t)) {
  c->w = w;
  c->h = h;
  c->px = NULL;
  c->dirty_x0 = c->dirty_x1 = NULL;
  /* The dirty spans are int16_t. */
  if (w <= 0 || h <= 0 || w > INT16_MAX || h > INT16_MAX) return -1;
  c->px = (uint16_t *)alloc((size_t)w * (size_t)h * sizeof(uint16_t));
  if (!c->px) return -1;
  memset(c->px, 0, (size_t)w * (size_t)h * sizeof(uint16_t));
  c->dirty_x0 = (int16_t *)malloc((size_t)h * sizeof(int16_t));
  c->dirty_x1 = (int16_t *)malloc((size_t)h * sizeof(int16_t));
  if (!c->dirty_x0 || !c->dirty_x1) {
    canvas_free(c);
    return -1;
  }
  mark_all_dirty(c);
  return 0;
}

void canvas_free(Canvas *c) {
  free(c->px);
  free(c->dirty_x0);
  free(c->dirty_x1);
  c->px = NULL;
  c->dirty_x0 = c->dirty_x1 = NULL;
}

uint16_t px_swap(uint16_t v) { return (uint16_t)((v << 8) | (v >> 8)); }

uint16_t rgb565(uint8_t r, uint8_t g, uint8_t b) {
  return px_swap((uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3)));
}

uint16_t rgb565_from16(uint16_t r, uint16_t g, uint16_t b) {
  return rgb565((uint8_t)(r >> 8), (uint8_t)(g >> 8), (uint8_t)(b >> 8));
}

bool canvas_dirty_row(const Canvas *c, int y, int *x0, int *x1) {
  if (y < 0 || y >= c->h || c->dirty_x0[y] > c->dirty_x1[y]) return false;
  *x0 = c->dirty_x0[y];
  *x1 = c->dirty_x1[y];
  return true;
}

void canvas_clear_dirty(Canvas *c) {
  for (int y = 0; y < c->h; y++) {
    c->dirty_x0[y] = (int16_t)c->w;
    c->dirty_x1[y] = -1;
  }
}

void canvas_clear(Canvas *c, uint16_t color) {
  for (int i = 0, n = c->w * c->h; i < n; i++) c->px[i] = color;
  mark_all_dirty(c);
}

void canvas_point(Canvas *c, int x, int y, uint16_t color) {
  if (x < 0 || y < 0 || x >= c->w || y >= c->h) return;
  c->px[(size_t)y * c->w + x] = color;
  mark_span(c, x, x, y);
}

static void hspan(Canvas *c, wide_t x0, wide_t x1, wide_t y, uint16_t color) {
  if (y < 0 || y >= c->h || x1 < 0 || x0 >= c->w) return;
  if (x0 < 0) x0 = 0;
  if (x1 >= c->w) x1 = c->w - 1;
  if (x0 > x1) return;
  mark_span(c, x0, x1, y);
  uint16_t *row = c->px + (size_t)y * c->w;
  for (int x = (int)x0, last = (int)x1; x <= last; x++) row[x] = color;
}

void canvas_fill_rect(Canvas *c, int x, int y, int w, int h, uint16_t color) {
  if (w <= 0 || h <= 0) return;
  wide_t x1 = (wide_t)x + w - 1, y1 = (wide_t)y + h - 1;
  wide_t y0 = y < 0 ? 0 : y;
  if (y1 >= c->h) y1 = c->h - 1;
  for (wide_t yy = y0; yy <= y1; yy++) hspan(c, x, x1, yy, color);
}

/* Liang-Barsky clip of the segment to [0,w-1]x[0,h-1]; false if outside. */
static int clip_line(const Canvas *c, double *x0, double *y0, double *x1,
                     double *y1) {
  double dx = *x1 - *x0, dy = *y1 - *y0, t0 = 0, t1 = 1;
  double p[4] = {-dx, dx, -dy, dy};
  double q[4] = {*x0, (c->w - 1) - *x0, *y0, (c->h - 1) - *y0};
  for (int i = 0; i < 4; i++) {
    if (p[i] == 0) {
      if (q[i] < 0) return 0;
    } else {
      double t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return 0;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return 0;
        if (t < t1) t1 = t;
      }
    }
  }
  double ax = *x0, ay = *y0;
  *x0 = ax + t0 * dx;
  *y0 = ay + t0 * dy;
  *x1 = ax + t1 * dx;
  *y1 = ay + t1 * dy;
  return 1;
}

void canvas_line(Canvas *c, int x0, int y0, int x1, int y1, uint16_t color) {
  double ax = x0, ay = y0, bx = x1, by = y1;
  int clipped = x0 < 0 || y0 < 0 || x0 >= c->w || y0 >= c->h || x1 < 0 ||
                y1 < 0 || x1 >= c->w || y1 >= c->h;
  if (clipped) {
    if (!clip_line(c, &ax, &ay, &bx, &by)) return;
    ax = floor(ax + 0.5);
    ay = floor(ay + 0.5);
    bx = floor(bx + 0.5);
    by = floor(by + 0.5);
  }
  int ix0 = (int)ax, iy0 = (int)ay, ix1 = (int)bx, iy1 = (int)by;
  int dx = abs(ix1 - ix0), sx = ix0 < ix1 ? 1 : -1;
  int dy = -abs(iy1 - iy0), sy = iy0 < iy1 ? 1 : -1;
  int err = dx + dy;
  for (;;) {
    canvas_point(c, ix0, iy0, color);
    if (ix0 == ix1 && iy0 == iy1) break;
    int e2 = 2 * err;
    if (e2 >= dy) {
      err += dy;
      ix0 += sx;
    }
    if (e2 <= dx) {
      err += dx;
      iy0 += sy;
    }
  }
}

void canvas_fill_ellipse(Canvas *c, int x, int y, int w, int h,
                         uint16_t color) {
  if (w <= 0 || h <= 0) return;
  double cx = x + (w - 1) / 2.0, cy = y + (h - 1) / 2.0;
  double rx = w / 2.0, ry = h / 2.0;
  wide_t y0 = y < 0 ? 0 : y, y1 = (wide_t)y + h - 1;
  if (y1 >= c->h) y1 = c->h - 1;
  for (wide_t yy = y0; yy <= y1; yy++) {
    double ny = (yy - cy) / ry;
    double t = 1.0 - ny * ny;
    if (t < 0) continue;
    double half = rx * sqrt(t);
    wide_t xa = (wide_t)ceil(cx - half), xb = (wide_t)floor(cx + half);
    if (xb < xa) continue;
    hspan(c, xa, xb, yy, color);
  }
}

/* Insertion sort is quadratic, and with software doubles a 1000-point Pedal
 * picture spent seconds in it. Past a handful of crossings qsort wins. */
#define SORT_INSERTION_MAX 16

static int compare_doubles(const void *a, const void *b) {
  double x = *(const double *)a, y = *(const double *)b;
  return (x > y) - (x < y);
}

void canvas_fill_polygon(Canvas *c, const int *xy, int n, uint16_t color) {
  if (n < 3) return;
  /* An edge crosses a scanline at most once, so n slots always suffice. The
   * heap is only used for big polygons, to keep the task stack small. */
  double stack_xs[64];
  double *xs = stack_xs;
  if (n > 64) {
    xs = (double *)malloc((size_t)n * sizeof(double));
    if (!xs) return;
  }
  wide_t ymin = xy[1], ymax = xy[1];
  for (int i = 1; i < n; i++) {
    if (xy[2 * i + 1] < ymin) ymin = xy[2 * i + 1];
    if (xy[2 * i + 1] > ymax) ymax = xy[2 * i + 1];
  }
  if (ymin < 0) ymin = 0;
  if (ymax >= c->h) ymax = c->h - 1;
  for (wide_t yy = ymin; yy <= ymax; yy++) {
    int nx = 0;
    double sy = yy + 0.5;
    for (int i = 0, j = n - 1; i < n; j = i++) {
      double yi = xy[2 * i + 1], yj = xy[2 * j + 1];
      if ((yi <= sy && yj > sy) || (yj <= sy && yi > sy)) {
        double t = (sy - yi) / (yj - yi);
        xs[nx++] = xy[2 * i] + t * (xy[2 * j] - xy[2 * i]);
      }
    }
    if (nx > SORT_INSERTION_MAX) {
      qsort(xs, (size_t)nx, sizeof(double), compare_doubles);
    } else {
      for (int a = 1; a < nx; a++)
        for (int b = a; b > 0 && xs[b - 1] > xs[b]; b--) {
          double tmp = xs[b];
          xs[b] = xs[b - 1];
          xs[b - 1] = tmp;
        }
    }
    for (int k = 0; k + 1 < nx; k += 2)
      hspan(c, (wide_t)ceil(xs[k] - 0.5), (wide_t)ceil(xs[k + 1] - 0.5) - 1, yy,
            color);
  }
  if (xs != stack_xs) free(xs);
}

/* Visible part of the rect as [x0,x1) x [y0,y1) in canvas coordinates; false
 * if none of it is visible. */
static bool visible_rect(const Canvas *c, int x, int y, int w, int h,
                         int *x0, int *y0, int *x1, int *y1) {
  if (w <= 0 || h <= 0) return false;
  wide_t lx = x < 0 ? 0 : x, ly = y < 0 ? 0 : y;
  wide_t rx = (wide_t)x + w, ry = (wide_t)y + h;
  if (rx > c->w) rx = c->w;
  if (ry > c->h) ry = c->h;
  if (lx >= rx || ly >= ry) return false;
  *x0 = (int)lx, *y0 = (int)ly, *x1 = (int)rx, *y1 = (int)ry;
  return true;
}

void canvas_copy_rect(const Canvas *c, int x, int y, int w, int h, uint16_t *dst) {
  int x0, y0, x1, y1;
  if (!visible_rect(c, x, y, w, h, &x0, &y0, &x1, &y1)) return;
  for (int py = y0; py < y1; py++)
    memcpy(dst + (size_t)(py - y) * w + (x0 - x), c->px + (size_t)py * c->w + x0,
           (size_t)(x1 - x0) * sizeof(uint16_t));
}

void canvas_paste_rect(Canvas *c, int x, int y, int w, int h, const uint16_t *src) {
  int x0, y0, x1, y1;
  if (!visible_rect(c, x, y, w, h, &x0, &y0, &x1, &y1)) return;
  for (int py = y0; py < y1; py++) {
    memcpy(c->px + (size_t)py * c->w + x0, src + (size_t)(py - y) * w + (x0 - x),
           (size_t)(x1 - x0) * sizeof(uint16_t));
    mark_span(c, x0, x1 - 1, py);
  }
}

void canvas_mark_dirty(Canvas *c, int x, int y, int w, int h) {
  int x0, y0, x1, y1;
  if (!visible_rect(c, x, y, w, h, &x0, &y0, &x1, &y1)) return;
  for (int py = y0; py < y1; py++) mark_span(c, x0, x1 - 1, py);
}

