  canvas_fill_rect(&c, 2, 1, 3, 2, C1);
  TEST_ASSERT_EQUAL_INT(2, dirty_row_count());
  assert_span(1, 2, 4);
  assert_span(2, 2, 4);
}

void test_drawing_that_clips_to_nothing_marks_nothing(void) {
