  canvas_point(&c, 0, 0, C1);
  canvas_point(&c, 7, 7, C1);
  canvas_fill_rect(&c, 5, 3, 10, 1, C1);
  assert_span(0, 0, 0);
  assert_span(3, 5, 7);
  assert_span(7, 7, 7);
}

void test_huge_coordinates_neither_overflow_nor_mark_stray_rows(void) {
