void test_overlay_text_is_erased_when_the_hack_changes_in_the_next_frame(void) {
  HackRunner *r = runner_create(&cv);
  TEST_ASSERT_EQUAL_INT(0, runner_start(r, 0));
  for (int f = 0; f < 30; f++) {
    runner_step(r);
    present();
  }
  stamp();
  present();
  unstamp();
  runner_next(r);
  runner_step(r);
  present();
  TEST_ASSERT_TRUE(shadow_matches_canvas());
  runner_destroy(r);
}

