void test_extreme_rect_coordinates_do_not_overflow(void) {
  uint16_t saved[1] = {0};
  canvas_copy_rect(&c, INT_MAX, INT_MAX, 5, 5, saved);
  canvas_paste_rect(&c, INT_MIN, INT_MIN, INT_MAX, INT_MAX, saved);
  TEST_ASSERT_EQUAL_INT(0, count_set());
